sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading) {
        return;
    }

    // Clear any previous field messages first
    g_form.hideFieldMsg('u_single_student_application');

    if (newValue == 'true') {
        g_form.showFieldMsg(
            'u_single_student_application', 
            'Switched to Single Student Application mode. Fill in Applicant Reference below.', 
            'info'
        );
        // Clear drive value if drive was previously set
        g_form.setValue('drive', '');
    } else {
        g_form.showFieldMsg(
            'drive', 
            'Drive mode active. This selection applies to multiple applicants.', 
            'info'
        );
        // Clear application value if application was previously set
        g_form.setValue('application', '');
    }
}
